import { useState } from "react";

export function App() {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button data-testid="modal-open" onClick={() => setOpen(true)}>Conditional modal open</button>
      {open ? <div role="dialog" data-testid="modal">Modal content</div> : null}
    </div>
  );
}
